/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];
let k, s;
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length == 2) {
    k = parseInt(lines[0]);
    s = lines[1];
  }

  if (k && lines.length == k + 2) {
    lines.shift();
    lines.shift();
    const commands = lines.map((str) => str.split(" "));

    console.log(getResult(s, commands));

    lines.length = 0;
  }
});

function getResult(s, commands) {
  let curIdx = 0;

  for (let [type, value] of commands) {
    switch (type) {
      case "FORWARD":
        curIdx += parseInt(value);
        curIdx = Math.min(curIdx, s.length);
        break;
      case "BACKWARD":
        curIdx -= parseInt(value);
        curIdx = Math.max(curIdx, 0);
        break;
      case "SEARCH-FORWARD":
        const i = s.indexOf(value, curIdx);
        if (i != -1) curIdx = i;
        break;
      case "SEARCH-BACKWARD":
        const i1 = s.lastIndexOf(value, curIdx);
        if (i1 != -1) curIdx = i1;
        break;
      case "INSERT":
        tmp = [...s];
        tmp.splice(curIdx, 0, ...value);
        s = tmp.join("");
        curIdx += value.length;
        break;
      case "REPLACE":
        tmp = [...s];
        tmp.splice(curIdx, value.length, ...value);
        s = tmp.join("");
        break;
      case "DELETE":
        tmp = [...s];
        tmp.splice(curIdx, parseInt(value));
        s = tmp.join("");
        break;
    }
  }

  return s;
}

